    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Uniform lines in the background color are empty space, not dividers.
    div_rows = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != bg]
    div_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != bg]

    def segments(size, dividers):
        result = []
        start = 0
        for d in dividers:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < size:
            result.append((start, size))
        return result

    row_parts = segments(h, div_rows)
    col_parts = segments(w, div_cols)

    # Find the compartment containing the most non-background cells.
    source = None
    best = -1
    for r0, r1 in row_parts:
        for c0, c1 in col_parts:
            score = sum(grid[r][c] != bg
                        for r in range(r0, r1)
                        for c in range(c0, c1))
            if score > best:
                best = score
                source = (r0, r1, c0, c1)

    if source is None:
        return [row[:] for row in grid]

    r0, r1, c0, c1 = source
    pattern = [grid[r][c0:c1] for r in range(r0, r1)]
    out = [row[:] for row in grid]

    for a, b in row_parts:
        for x, y in col_parts:
            if b - a == len(pattern) and y - x == len(pattern[0]):
                for i in range(len(pattern)):
                    out[a + i][x:y] = pattern[i][:]

    return out
